D={
82318:("No banco","**I'd like to… Could you…?** Termos: *withdraw, deposit, transfer, interest rate*.",[("{{I'd like to open}} an account.","Gostaria de abrir uma conta."),("{{Could you check}} my balance?","Poderia conferir meu saldo?"),("{{What's the interest rate}}?","Qual é a taxa de juros?"),("I want to {{withdraw}} some cash.","Quero sacar um dinheiro.")],"“Withdraw” =",["sacar","depositar","transferir"],0,"Sacar."),
82319:("Seguros","Passado e passivo: **The car was damaged. The claim was approved.** *Does it cover…? What is the excess?*",[("I had an {{accident}}.","Sofri um acidente."),("The car {{was damaged}}.","O carro foi danificado."),("{{Does it cover}} theft?","Cobre roubo?"),("The claim {{was approved}}.","O pedido foi aprovado.")],"“Cover” (seguro) =",["cobrir/incluir","tampar","esconder"],0,"Cobertura."),
82320:("Vizinhos","**Should** (o que é bom); **Can I borrow…? Could you keep the noise down?**; *We're having a block party.*",[("Neighbors {{should look out}} for each other.","Vizinhos deveriam cuidar uns dos outros."),("{{Can I borrow}} your ladder?","Posso pegar sua escada emprestada?"),("{{Could you keep the noise down}}?","Pode baixar o barulho?"),("We're having a {{block party}}.","Vamos fazer uma festa de rua.")],"“Keep the noise down” =",["baixar o barulho","guardar o barulho","fazer barulho"],0,"Reduzir."),
82321:("Bichos de estimação","Presente (rotina), passado (adoção), **have to** (obrigação).",[("I {{feed}} him twice a day.","Alimento-o duas vezes ao dia."),("We {{adopted}} him in May.","Nós o adotamos em maio."),("We {{have to}} walk him every day.","Temos de levá-lo para passear todo dia."),("He {{loves}} the park.","Ele adora o parque.")],"“Adopt” =",["adotar","adaptar","aprovar"],0,"Adotar."),
82322:("Jardinagem","Passado (o que fez), **will** (previsão), **spend time + -ing**.",[("I {{spent}} the morning {{pulling}} weeds.","Passei a manhã arrancando ervas daninhas."),("Beans {{grow}} quickly.","Feijões crescem rápido."),("The roses {{will bloom}} soon.","As rosas vão florescer logo."),("I {{planted}} tomatoes.","Plantei tomates.")],"Qual está certa?",["I spent time to garden.","I spent time gardening.","I spent time garden."],1,"Spend time + -ing."),
930069:("collocations adjetivo + substantivo","**Strong coffee, heavy rain, high price, deep sleep, slim chance**.",[("I'd like a {{strong}} coffee.","Gostaria de um café forte."),("{{Heavy}} rain is coming.","Vem chuva forte."),("A {{high}} price.","Um preço alto."),("There's a {{slim}} chance.","Há uma chance pequena.")],"Qual combina com “rain”?",["strong","heavy","big"],1,"Heavy rain."),
82323:("Consertos em casa","Presente contínuo (problemas), **should** (sugestão), **have something done**.",[("The tap {{is dripping}}.","A torneira está pingando."),("We {{should hire}} a plumber.","Deveríamos contratar um encanador."),("We {{had the roof repaired}}.","Mandamos consertar o telhado."),("{{Can you fix}} it today?","Pode consertar hoje?")],"“Leaky” =",["com vazamento","rápido","novo"],0,"Vazando."),
82324:("Faxina","**I'll** (oferta), **have to** (obrigação), divisão de tarefas.",[("{{I'll take out}} the trash.","Eu levo o lixo para fora."),("We {{have to do}} the laundry.","Temos de lavar a roupa."),("You wash, {{I'll dry}}.","Você lava, eu seco."),("{{Can you vacuum}} the room?","Pode aspirar o quarto?")],"“I'll” oferece…",["ajuda","obrigação","dúvida"],0,"Oferta."),
82325:("Moda","**Wear, fit, suit, match**: *It fits well. It matches your shoes.* *Can I try this on?*",[("This jacket doesn't {{fit}} me.","Esta jaqueta não me serve."),("{{Can I try on}} this dress?","Posso experimentar este vestido?"),("{{What size}} do you wear?","Que tamanho você usa?"),("It {{matches}} your shoes.","Combina com seus sapatos.")],"“Fit” =",["servir (tamanho)","caber dentro","gostar"],0,"Servir."),
82326:("Economizar","**Should / try to / don't** e **if**: *You should make a budget. If you save, you'll buy it.*",[("You {{should make}} a budget.","Você deveria fazer um orçamento."),("{{Try to}} cut back.","Tente reduzir."),("{{Don't waste}} food.","Não desperdice comida."),("If I save, I'{{ll buy}} it later.","Se eu economizar, compro depois.")],"Qual é um conselho?",["You should make a budget.","You made a budget.","I make a budget."],0,"Should."),
82327:("Ideias de presentes","**How about…? Why don't you…? You could…** *It's the thought that counts.*",[("{{How about}} a scarf?","Que tal um cachecol?"),("{{Why don't you}} check her list?","Por que não vê a lista dela?"),("{{You could}} buy flowers.","Você poderia comprar flores."),("{{It's the thought that counts}}.","O que importa é a intenção.")],"“It's the thought that counts” =",["o que vale é a intenção","pense antes","o pensamento custa"],0,"A intenção."),
930070:("point out / sum up","**Point out** = apontar; **sum up** = resumir; **go over** = revisar; **bring up** = trazer um assunto.",[("I'd like to {{point out}} one detail.","Gostaria de apontar um detalhe."),("Let me {{sum up}} the report.","Deixe-me resumir o relatório."),("Let's {{go over}} the plan.","Vamos revisar o plano."),("Don't {{bring up}} that again.","Não traga isso de novo.")],"“Sum up” =",["resumir","somar tudo","subir"],0,"Resumir."),
82328:("Fazer um brinde","**I'd like to propose a toast. Here's to… To…! Please raise your glasses.**",[("{{I'd like to propose a toast}}.","Gostaria de propor um brinde."),("{{Here's to}} your health!","À sua saúde!"),("{{To new beginnings}}!","A novos começos!"),("{{Please raise}} your glasses.","Por favor, levantem seus copos.")],"“Here's to you” =",["um brinde a você","aqui para você","aqui está você"],0,"Brinde."),
82329:("Revisão: tempos do passado","Passado simples (terminado), contínuo (fundo), **past perfect** (antes), **used to** (hábito).",[("I {{moved}} two years ago.","Mudei-me há dois anos."),("I {{was walking}} when it rained.","Eu caminhava quando choveu."),("She {{had left}} before I arrived.","Ela tinha saído antes de eu chegar."),("I {{used to}} live there.","Eu morava lá.")],"Qual é “antes de outro fato”?",["moved","was walking","had left"],2,"Past perfect."),
82330:("Revisão: present perfect","**Have/has + particípio**; *just, ever, never, yet*; **for** = duração; **since** = início.",[("I {{have lived}} here {{for}} years.","Moro aqui há anos."),("I've {{just}} finished.","Acabei de terminar."),("{{Have you ever}} been to Rome?","Você já esteve em Roma?"),("I haven't called {{yet}}.","Ainda não liguei.")],"Complete: “since 2020” combina com…",["present perfect","past simple","will"],0,"Since + present perfect."),
82331:("Revisão: condicionais","**Zero** (fato), **first** (real), **second** (irreal), **wish + passado** (desejo).",[("If it rains, we'{{ll stay}} home.","Se chover, ficaremos em casa."),("If I {{had}} money, I {{would travel}}.","Se eu tivesse dinheiro, viajaria."),("If you heat ice, it {{melts}}.","Se aquece gelo, ele derrete."),("I {{wish}} I {{could}} fly.","Queria poder voar.")],"Qual é irreal?",["If I had wings, I'd fly.","If it rains, I'll stay.","If you heat ice, it melts."],0,"Second conditional."),
930071:("idioms de dinheiro","**Cost an arm and a leg**, **break the bank**, **make ends meet**, **pay through the nose**.",[("It {{costs an arm and a leg}} here.","Custa os olhos da cara aqui."),("It won't {{break the bank}}.","Não vai estourar o orçamento."),("I can barely {{make ends meet}}.","Mal consigo fechar as contas."),("We {{paid through the nose}}.","Pagamos uma fortuna.")],"“Make ends meet” =",["pagar as contas","encontrar o fim","terminar a corda"],0,"Fechar as contas."),
82332:("Revisão: passivo e indireto","Passivo: **was/were + particípio**. Indireto: recue o tempo; *asked if*.",[("The house {{was built}} in 1900.","A casa foi construída em 1900."),("She said the house {{was}} old.","Ela disse que a casa era velha."),("They asked {{if}} we were ready.","Perguntaram se estávamos prontos."),("He told me {{to wait}}.","Ele me mandou esperar.")],"“Is” no discurso indireto vira…",["was","is","were"],0,"Is → was."),
82333:("Revisão: conectores","**Although** + oração; **despite** + substantivo; **however** abre frase; **because** = causa; **so** = resultado.",[("{{Although}} it rained, we went out.","Embora chovesse, saímos."),("{{Despite}} the rain, we went out.","Apesar da chuva, saímos."),("{{However}}, it was cold.","No entanto, fazia frio."),("It rained, {{so}} we stayed in.","Choveu, então ficamos.")],"Qual vem antes de substantivo?",["although","despite","however"],1,"Despite."),
82334:("Revisão: -ing e to","**Enjoy/avoid/suggest + -ing**; **decide/promise/want + to**; **let/make + base**.",[("I {{enjoy swimming}} in the sea.","Gosto de nadar no mar."),("We {{decided to leave}}.","Decidimos partir."),("They {{let us go}}.","Eles nos deixaram ir."),("She {{promised to call}}.","Ela prometeu ligar.")],"Qual está certa?",["I enjoy to swim.","I enjoy swimming.","I enjoy swim."],1,"Enjoy + -ing."),
82335:("Revisão: dedução e conselho","**Must have** (quase certo), **might have** (possível), **can't have** (impossível), **should have** (arrependimento).",[("She {{must have left}} already.","Ela deve ter saído já."),("You {{should have called}} me.","Você devia ter me ligado."),("He {{can't have done}} it.","Ele não pode ter feito isso."),("It {{might have been}} an error.","Pode ter sido um erro.")],"“Can't have done” =",["é impossível que tenha feito","talvez tenha feito","fez"],0,"Impossível."),
82336:("Revisão: phrasal verbs","**Run into** = encontrar; **give up** = desistir; **figure out** = descobrir. Pronome no meio: *figure it out*.",[("I {{ran into}} an old friend.","Esbarrei num velho amigo."),("Don't {{give up}} now.","Não desista agora."),("We need to {{figure}} it {{out}}.","Precisamos descobrir isso."),("Please {{turn}} it {{off}}.","Desligue isso, por favor.")],"Qual está certa?",["figure out it","figure it out","out figure it"],1,"Pronome no meio."),
930072:("sentimentos","**Nervous about**, **anxious about**, **relieved**, **proud of**, **afraid of**.",[("I feel {{nervous}} about tomorrow.","Estou nervoso com amanhã."),("I'm {{proud of}} you.","Tenho orgulho de você."),("She was {{relieved}}.","Ela ficou aliviada."),("I'm {{afraid of}} heights.","Tenho medo de altura.")],"Qual está certa?",["afraid from","afraid of","afraid in"],1,"Afraid of."),
82337:("Conversa real 1","Marcadores: **Honestly, Actually, Anyway, By the way**. Novidades: *I've been busy lately.*",[("{{Honestly}}, I'm tired.","Sinceramente, estou cansado."),("{{Actually}}, I changed jobs last month.","Na verdade, mudei de emprego mês passado."),("{{Anyway}}, how are you?","Enfim, como você está?"),("I've {{been busy lately}}.","Tenho andado ocupado.")],"“By the way” introduz…",["algo novo","uma despedida","uma ordem"],0,"Acréscimo."),
82338:("Conversa de trabalho","**Let's touch base. I'll get back to you. Can you send me an update? The deadline is…**",[("{{Let's touch base}} on Friday.","Vamos nos falar na sexta."),("{{I'll get back to you}} tomorrow.","Respondo a você amanhã."),("{{Can you send me an update}}?","Pode me enviar uma atualização?"),("{{The deadline is}} Monday.","O prazo é segunda.")],"“Get back to you” =",["responder depois","voltar atrás","pegar de volta"],0,"Retornar contato."),
82339:("Conversa social","**I was wondering if…** *Would you like to…?* Aceite: *That sounds lovely.* Recuse: *I'm afraid I can't.*",[("{{I was wondering if}} you're free.","Eu estava me perguntando se você está livre."),("Maybe we could have {{lunch}}.","Talvez pudéssemos almoçar."),("{{That sounds lovely}}.","Parece ótimo."),("{{I'm afraid I can't}}.","Receio que não possa.")],"“I was wondering if…” soa…",["mais gentil","mais bravo","mais curto"],0,"Mais gentil."),
82340:("Conversa de viagem","**Within walking distance**, **a return ticket**, **How long does it take?**, *Thanks a million*.",[("Is it {{within walking distance}}?","Dá para ir a pé?"),("I'd like {{a return ticket}}, please.","Gostaria de um bilhete de ida e volta."),("{{How long does it take}}?","Quanto tempo leva?"),("{{Thanks a million}} for your help.","Muito obrigado pela ajuda.")],"“Return ticket” =",["ida e volta","só ida","bilhete perdido"],0,"Ida e volta."),
82341:("Estratégias de leitura","**Skim** (visão geral), **scan** (achar um detalhe), use o contexto e adivinhe.",[("{{First}}, skim the text.","Primeiro, leia por cima."),("You can {{guess}} the meaning.","Você pode adivinhar o significado."),("Use the {{context}}.","Use o contexto."),("{{Scan}} for the date.","Procure rapidamente a data.")],"“Scan” =",["buscar um detalhe","ler tudo devagar","copiar"],0,"Procurar um dado."),
930073:("count on / rely on","**Count on / rely on** = contar com; **depend on** = depender de; **look up to** = admirar.",[("You can {{count on}} my friends.","Você pode contar com meus amigos."),("It {{depends on}} you.","Depende de você."),("I {{look up to}} my teacher.","Admiro minha professora."),("We {{rely on}} each other.","Confiamos um no outro.")],"“Rely on” =",["contar com","gostar de","depender de dinheiro"],0,"Contar com."),
82342:("Estratégias de escuta","Primeiro a **ideia geral**; depois os **detalhes**. *Could you repeat that? Could you speak more slowly?*",[("{{Listen for the gist}}.","Ouça a ideia geral."),("{{Could you repeat that}}, please?","Poderia repetir, por favor?"),("{{Could you speak more slowly}}?","Poderia falar mais devagar?"),("Then listen for the {{details}}.","Depois ouça os detalhes.")],"“Gist” =",["ideia geral","detalhe","nota"],0,"Essência."),
82343:("Falar com fluência","**Practice every day, don't stop, short pauses.** *Let me think… Well…* **Keep + -ing**.",[("Fluency comes with {{practice}}.","A fluência vem com prática."),("Just {{keep going}}.","Apenas continue."),("Try not to use too many {{fillers}}.","Tente não usar muitas muletas."),("{{Let me think}}…","Deixe-me pensar…")],"“Keep going” =",["continuar","parar","correr"],0,"Continuar."),
82344:("Escrever com clareza","Etapas: **draft, check, edit**. Frases curtas, conectores, leia em voz alta.",[("{{Write}} a first draft quickly.","Escreva um primeiro rascunho rápido."),("{{Keep}} your sentences short.","Mantenha suas frases curtas."),("{{Read}} it aloud.","Leia em voz alta."),("{{Check}} the spelling last.","Confira a ortografia por último.")],"Qual vem por último?",["write a draft","check spelling","edit"],1,"Ortografia no fim."),
82345:("Pronúncia","**Stress the right syllable, use intonation, record yourself.** Imperativos: *Listen. Repeat. Record.*",[("{{Stress}} the right syllable.","Acentue a sílaba certa."),("{{Record yourself}} and listen.","Grave a si mesmo e ouça."),("{{Repeat}} slowly.","Repita devagar."),("Everyone has an {{accent}}.","Todo mundo tem sotaque.")],"“Stress” (pronúncia) =",["ênfase na sílaba","estresse","dor"],0,"Acento tônico."),
82346:("Vocabulário","**Keep a notebook, learn in context, review regularly.** Prefira frases a listas.",[("{{Keep}} a vocabulary notebook.","Mantenha um caderno de vocabulário."),("{{Learn}} new words in context.","Aprenda palavras novas em contexto."),("{{Review}} regularly.","Revise regularmente."),("Use {{synonyms}} to vary.","Use sinônimos para variar.")],"Qual é melhor?",["memorizar listas","aprender em frases","copiar tudo"],1,"Contexto."),
930074:("trocas e devoluções","**I'd like to return this. Do you have the receipt? Can I exchange it?**",[("{{I'd like to return}} this.","Gostaria de devolver isto."),("{{Do you have the receipt}}?","Você tem o recibo?"),("{{Can I exchange it}} for a bigger size?","Posso trocá-lo por um tamanho maior?"),("{{I'd like a refund}}.","Gostaria de reembolso.")],"“Exchange” =",["trocar","expor","exceder"],0,"Trocar."),
81278:("un- / -ful / -less","**Un-** = oposto; **-ful** = cheio de; **-less** = sem.",[("happy → {{un}}happy","feliz → infeliz"),("care → care{{ful}}","cuidado → cuidadoso"),("care → care{{less}}","cuidado → descuidado"),("This is very help{{ful}}.","Isto é muito útil.")],"“Careless” =",["descuidado","cuidadoso","cuidado"],0,"Sem cuidado."),
82347:("Aprender com erros","**Make a mistake, learn from mistakes, keep trying.** Erros comuns: artigos, preposições e o -s da 3ª pessoa.",[("Everyone {{makes mistakes}}.","Todo mundo comete erros."),("I'm slowly {{getting better}}.","Estou melhorando aos poucos."),("{{Learn from}} your mistakes.","Aprenda com seus erros."),("{{Keep trying}}!","Continue tentando!")],"Qual está certa?",["make a mistake","do a mistake","create a mistake"],0,"Make a mistake."),
82348:("Desafio B1","**Present perfect** (o que já alcançou), **can** (o que consegue), **want to** (metas).",[("I've {{learned}} so much English.","Aprendi tanto inglês."),("I {{can express}} my opinion.","Consigo expressar minha opinião."),("I {{want to improve}} even more.","Quero melhorar ainda mais."),("I've {{made}} great progress.","Fiz grande progresso.")],"Qual mostra uma meta?",["I want to improve.","I improved.","I improve."],0,"Want to."),
82349:("Olhar para trás","Compare **antes e agora**: *I used to be shy, but now I can talk.* **Proud of**.",[("I used to be {{shy}}.","Eu era tímido."),("Now I can {{talk}} freely.","Agora consigo falar livremente."),("I've {{made great progress}}.","Fiz grande progresso."),("I'm very {{proud of}} myself.","Tenho muito orgulho de mim.")],"Qual mostra o passado?",["I used to be shy.","I am confident.","I will speak."],0,"Used to."),
82350:("Rumo ao B2","Metas: **I want to, I'm going to, I will**; **be ready for**.",[("{{I'm going to}} master English.","Vou dominar o inglês."),("{{I will}} face bigger challenges.","Vou enfrentar desafios maiores."),("{{I'm ready for}} the next step.","Estou pronto para o próximo passo."),("{{I want to}} keep learning.","Quero continuar aprendendo.")],"“Be ready for” =",["estar pronto para","estar lendo","estar pesado"],0,"Pronto para."),
930075:("Diga melhor","Troque palavras simples por mais precisas: **excellent, terrible, huge, delighted, exhausted, furious**. *Absolutely* combina com elas; *very* com adjetivos comuns.",[("It was {{excellent}} yesterday.","Foi excelente ontem."),("I'm {{delighted}} to see you.","Estou encantado em ver você."),("I'm {{exhausted}} after work.","Estou exausto depois do trabalho."),("He was {{furious}}.","Ele estava furioso.")],"Qual combina com “absolutely”?",["very good","absolutely amazing","absolutely nice"],1,"Adjetivo forte."),
}
